            colorCount.put(color, colorCount.getOrDefault(color, 0) + 1);
        }
        return colorCount;
    }

    public static Pair<Integer, String> mostPopularColor(List<Car> cars) {
        Map<String, Integer> colorCount = countColors(cars);
        String mostPopularColor = "";
        int maxCount = 0;
        for (Map.Entry<String, Integer> entry : colorCount.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                mostPopularColor = entry.getKey();
            }
        }
        return new Pair<>(maxCount, mostPopularColor);
    }

    public static void main(String[] args) {
        List<Car> cars = List.of(
            new Car("Red"),
            new Car("Blue"),
            new Car("Red"),
            new Car("Green"),
            new Car("Blue"),
            new Car("Red")
        );

